  // 再切回来时刚填的内容就全没了，所以后台刷新必须静默。
  async function load(options: { silent?: boolean } = {}) { if (!options.silent) setLoading(true); setError(""); try { const [po, ib, payable, entries, ms, us, ss, bs, so] = await Promise.all([apiGet<PurchaseOrder[]>("/purchase-orders"), apiGet<Inbound[]>("/raw-material-inbounds"), apiGet<PayableSource[]>("/payable-sources"), apiGet<PayableEntry[]>("/finance/payable-entries").catch(() => ({ data: [] as PayableEntry[], meta: {} })), apiGet<Reference[]>("/materials"), apiGet<Reference[]>("/units"), apiGet<Reference[]>("/suppliers"), apiGet<Reference[]>("/boms"), apiGet<Reference[]>("/sales-orders")]); setOrders(po.data); setInbounds(ib.data); setPayables(payable.data); setPayableEntries(entries.data); setMaterials(ms.data); setUnits(us.data); setSuppliers(ss.data); setBoms(bs.data); setSalesOrders(so.data); } catch (cause) { setError(messageOf(cause, "采购数据加载失败")); } finally { if (!options.silent) setLoading(false); } }
  useEffect(() => { void load(); }, []);
